package com.hbm.item.coordinate;
import java.util.List;import net.minecraft.ChatFormatting;import net.minecraft.core.BlockPos;import net.minecraft.core.component.DataComponents;import net.minecraft.network.chat.Component;import net.minecraft.world.InteractionResult;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.item.component.CustomData;import net.minecraft.world.item.context.UseOnContext;import net.minecraft.world.level.Level;
/** Original ItemCoordinateBase, a real reusable source linking item contract, not a duplicate coordinate format. */
public abstract class CoordinateItem extends Item{protected CoordinateItem(){super(new Properties().stacksTo(1));}public static BlockPos position(ItemStack stack){if(!stack.has(DataComponents.CUSTOM_DATA))return null;var tag=stack.get(DataComponents.CUSTOM_DATA).copyTag();return new BlockPos(tag.getInt("posX"),tag.getInt("posY"),tag.getInt("posZ"));}protected abstract boolean canGrab(Level level,BlockPos pos);protected boolean includeY(){return true;}protected BlockPos coordinates(Level level,BlockPos pos){return pos;}protected void targetSet(Level level,BlockPos pos,Player player){}@Override public InteractionResult useOn(UseOnContext c){if(!canGrab(c.getLevel(),c.getClickedPos()))return InteractionResult.PASS;if(!c.getLevel().isClientSide){var pos=coordinates(c.getLevel(),c.getClickedPos());CustomData.update(DataComponents.CUSTOM_DATA,c.getItemInHand(),tag->{tag.putInt("posX",pos.getX());if(includeY())tag.putInt("posY",pos.getY());tag.putInt("posZ",pos.getZ());});targetSet(c.getLevel(),pos,c.getPlayer());}return InteractionResult.sidedSuccess(c.getLevel().isClientSide);}@Override public void appendHoverText(ItemStack stack,TooltipContext context,List<Component> lines,TooltipFlag flag){var p=position(stack);if(p==null)lines.add(Component.translatable("tooltip.hbm.coordinate.unset").withStyle(ChatFormatting.RED));else{lines.add(Component.literal("X: "+p.getX()));if(includeY())lines.add(Component.literal("Y: "+p.getY()));lines.add(Component.literal("Z: "+p.getZ()));}}}
